class Solution {
public:
    int minMergedInteger(vector<int>& nums) {
        long long best = LLONG_MAX;
        for (size_t i = 0; i < nums.size(); i += 2) {
            int a = nums[i];
            int b = nums[i + 1];
            // count digits of b
            int d = 0;
            int tmp = b;
            while (tmp > 0) {
                ++d;
                tmp /= 10;
            }
            long long mul = 1;
            for (int k = 0; k < d; ++k) mul *= 10;
            long long merged = static_cast<long long>(a) * mul + b;
            if (merged < best) best = merged;
        }
        return static_cast<int>(best);
    }
};
